def cache_sim(capacity, ttl, ops):
    from collections import OrderedDict

    cache = OrderedDict()  # {key: (value, write_time)}
    results = []

    for op in ops:
        if op[0] == 'put':
            _, t, key, value = op

            # Remove expired entries
            expired_keys = [k for k, (_, write_time) in cache.items() if t >= write_time + ttl]
            for k in expired_keys:
                del cache[k]

            # If key exists, remove it first (will re-add at end for LRU)
            if key in cache:
                del cache[key]

            # If at capacity and adding a new key, evict LRU
            if len(cache) >= capacity and key not in cache:
                cache.popitem(last=False)

            # Add the new entry (most recently used)
            cache[key] = (value, t)

        elif op[0] == 'get':
            _, t, key = op

            # Remove expired entries
            expired_keys = [k for k, (_, write_time) in cache.items() if t >= write_time + ttl]
            for k in expired_keys:
                del cache[k]

            # Get the entry if it exists
            if key in cache:
                value, write_time = cache[key]
                # Move to end (most recently used)
                del cache[key]
                cache[key] = (value, write_time)
                results.append(value)
            else:
                results.append(-1)

    return results

